// revenuecat-reconcile — OI-519 (+51). Hourly cron. Thin shell; the run lives in logic.ts (tested in index_test.ts).
// Cron auth via _shared/cron_auth.ts; telemetry via _shared/cron_telemetry.ts (CLAUDE.md section 4.5).
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";
import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
import { logCronEnd, logCronStart } from "../_shared/cron_telemetry.ts";
import {
  isMirrorEnabled,
  mirrorRevenueCatCustomer,
  PLAY_SUBSCRIPTION_ID,
  REVENUECAT_API_BASE,
  REVENUECAT_SECRET_ENV,
  REVENUECAT_TIMEOUT_MS,
  type ServiceClient,
  supabaseMirrorDb,
} from "../_shared/revenuecat_mirror.ts";
import {
  DRAIN_BATCH,
  FN_NAME,
  handler,
  mergeReconcileCandidates,
  type ReconcileDb,
  type ReconcileDeps,
  SWITCH_OFF_CATCH_UP_DAYS,
  switchOffCatchUpUids,
} from "./logic.ts";
import { fetchAllPages } from "../_shared/paged_fetch.ts";

const H = 3600 * 1000;

export function reconcileDb(client: ServiceClient): ReconcileDb {
  const iso = (ms: number) => new Date(ms).toISOString();
  const count = async (q: PromiseLike<{ count: number | null; error: unknown }>) => {
    const { count: n, error } = await q;
    if (error) throw new Error("deferral count failed");
    return n ?? 0;
  };
  return {
    stallCounts: async (now) => ({
      pendingOld: await count(client.from("store_reward_deferrals").select("id", { count: "exact", head: true })
        .eq("status", "pending").lt("created_at", iso(now - 24 * H))),
      inFlightOld: await count(client.from("store_reward_deferrals").select("id", { count: "exact", head: true })
        .eq("status", "in_flight").lt("claimed_at", iso(now - 2 * H))),
      needsCheck: await count(client.from("store_reward_deferrals").select("id", { count: "exact", head: true })
        .eq("status", "needs_check")),
    }),
    reconcileUids: async (now) => {
      const { data, error } = await client.from("subscriptions").select("user_id").eq("store", "play")
        .or(`and(end_date.gte.${iso(now - 72 * H)},end_date.lte.${iso(now + 24 * H)}),and(status.eq.active,store_read_at.lt.${iso(now - 24 * H)})`)
        .order("store_read_at", { ascending: true })
        .limit(200);
      if (error) throw new Error("reconcile candidates read failed");
      // Plus every user whose webhook arrived while the switch was OFF and who has not been read since (a purchase made
      // between the deploy and the switch ON, or during a rollback, would otherwise never be mirrored).
      const regular = (data ?? []).map((r: { user_id: string }) => r.user_id);
      // The catch-up is best effort: any failure (a read error, more than 20 pages of events) skips it for this run and
      // never costs the regular candidates (B-pass round 2 on the hermes fixes).
      let catchUp: string[] = [];
      try {
        // Paged, newest first: one noisy user's events must not hide another user's (dedupe AFTER every page; B-pass on
        // the hermes fixes, seat A).
        type Ev = { user_id: string | null; received_at: string };
        const events = await fetchAllPages<Ev>(
          () => client.from("subscription_events").select("user_id, received_at").eq("outcome", "switch_off")
            .not("user_id", "is", null).gte("received_at", iso(now - SWITCH_OFF_CATCH_UP_DAYS * 24 * H)),
          { orderBy: [{ column: "id", ascending: false }], pageSize: 1000, maxPages: 20, label: "revenuecat-reconcile switch-off events" },
        );
        // The 200 most recent distinct users (one Play row each, so one read row each).
        const evUids = [...new Set<string>(events.map((r) => r.user_id).filter((u): u is string => !!u))].slice(0, 200);
        let reads: { user_id: string; store_read_at: string | null }[] = [];
        if (evUids.length > 0) {
          const rd = await client.from("subscriptions").select("user_id, store_read_at").eq("store", "play")
            .in("user_id", evUids).limit(400);
          if (rd.error) throw new Error("switch-off catch-up reads failed");
          reads = rd.data ?? [];
        }
        catchUp = switchOffCatchUpUids(events.filter((e) => e.user_id && evUids.includes(e.user_id)), reads);
      } catch (e) {
        console.warn(`[revenuecat-reconcile] switch-off catch-up skipped this run: ${(e as { name?: string })?.name ?? "error"}`);
      }
      return mergeReconcileCandidates(regular, catchUp);
    },
    crashedInFlight: async (now) => {
      const { data, error } = await client.from("store_reward_deferrals").select("id, claim_token")
        .eq("status", "in_flight").lt("claimed_at", iso(now - H)).limit(50);
      if (error) throw new Error("in-flight read failed");
      return (data ?? []).map((r: { id: string; claim_token: string }) => ({ id: r.id, token: r.claim_token }));
    },
    pendingRows: async (limit) => {
      if (limit !== DRAIN_BATCH) throw new Error("pendingRows reads exactly one drain batch");
      const { data, error } = await client.from("store_reward_deferrals").select("id, user_id, days")
        .eq("status", "pending").order("updated_at", { ascending: true }).order("created_at", { ascending: true }).limit(20); // = DRAIN_BATCH (a literal for the read gate)
      if (error) throw new Error("pending read failed");
      return data ?? [];
    },
    touch: async (id) => {
      const { error } = await client.from("store_reward_deferrals").update({ updated_at: new Date().toISOString() })
        .eq("id", id).eq("status", "pending").select("id").order("id").limit(1); // PGRST109, as in claim
      if (error) throw new Error("touch failed");
    },
    claim: async (id) => {
      const token = crypto.randomUUID();
      const { data, error } = await client.from("store_reward_deferrals")
        .update({ status: "in_flight", claim_token: token, claimed_at: new Date().toISOString(), updated_at: new Date().toISOString() })
        .eq("id", id).eq("status", "pending").select("id").order("id").limit(1); // PostgREST refuses a limited UPDATE without an order on a unique column (PGRST109)
      if (error) {
        if ((error as { code?: string }).code === "23505") return null; // another defer in flight for this user
        throw new Error("claim failed");
      }
      return Array.isArray(data) && data.length === 1 ? token : null;
    },
    mark: async (id, token, status) => {
      const { data, error } = await client.from("store_reward_deferrals")
        .update({ status, updated_at: new Date().toISOString(), ...(status === "pending" ? { claim_token: null, claimed_at: null } : {}) })
        .eq("id", id).eq("status", "in_flight").eq("claim_token", token).select("id").order("id").limit(1); // PGRST109, as in claim
      if (error) throw new Error("mark failed");
      return Array.isArray(data) && data.length === 1;
    },
    fallBack: async (id, token) => {
      // oi79-ok: store_reward_fall_back RETURNS text (one scalar).
      const { data, error } = await client.rpc("store_reward_fall_back", { p_id: id, p_token: token });
      if (error) throw new Error(`fall back failed: ${(error as { code?: string }).code ?? "unknown"}`);
      return String(data);
    },
  };
}

async function postDefer(uid: string, days: number): Promise<number> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), REVENUECAT_TIMEOUT_MS);
  try {
    const res = await fetch(
      `${REVENUECAT_API_BASE}/subscribers/${encodeURIComponent(uid)}/subscriptions/${PLAY_SUBSCRIPTION_ID}/defer`,
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${Deno.env.get(REVENUECAT_SECRET_ENV) ?? ""}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ extend_by_days: days }),
        signal: ctrl.signal,
      },
    );
    await res.body?.cancel();
    return res.status;
  } finally {
    clearTimeout(timer);
  }
}

function realDeps(): ReconcileDeps {
  const client = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
  const mdb = supabaseMirrorDb(client);
  return {
    authorized: (req) => isAuthorizedCronCall(req),
    telemetryStart: () => logCronStart("revenuecat-reconcile"), // a literal: the cron_call_log roster reads it (= FN_NAME)
    telemetryEnd: (id, status, opts) => logCronEnd(id, status, opts),
    mirrorEnabled: () => isMirrorEnabled(),
    db: reconcileDb(client),
    mirror: (uid) => mirrorRevenueCatCustomer(uid, { db: mdb, secretKey: Deno.env.get(REVENUECAT_SECRET_ENV) }),
    postDefer,
    alert: (source, summary, context) => mdb.alert(source, "warn", summary, context),
  };
}

if (import.meta.main) serve((req) => handler(req, realDeps()));

/**
 * cron_auth.ts — shared-secret auth gate for cron-dispatched Edge Functions.
 *
 * Rewritten 2026-07-26 (closes-diagnose: c3f8a1). See HISTORY at the bottom —
 * the two previous designs both failed in production, and the second failed
 * silently for roughly eight weeks.
 *
 * AUTH MODEL
 * ----------
 * A single opaque shared secret. The caller must present
 * `Authorization: Bearer <CRON_SECRET>`, where `CRON_SECRET` is an Edge
 * Function secret whose value also lives in the Vault row `cron_secret`, read
 * by `private.cron_get_secret()` and interpolated into every `cron.job`
 * command (migrations 107/108).
 *
 * WHY A SHARED SECRET RATHER THAN A JWT
 * -------------------------------------
 * This is machine-to-machine auth between pg_cron and the Edge runtime. There
 * is no user identity to carry, no claims to inspect and no delegation — a
 * signed token buys nothing here, and every JWT-shaped attempt has coupled the
 * gate to platform key management that then changed underneath it:
 *
 *   - Attempt 1 compared the token to `SUPABASE_SERVICE_ROLE_KEY`. Broke when
 *     the Vault copy and the env copy drifted (diagnose 5a65bd).
 *   - Attempt 2 verified the signature against `SUPABASE_JWT_SECRET` — a
 *     variable Supabase does not inject and **forbids creating**, because the
 *     platform reserves the `SUPABASE_` prefix for secret names. Unsatisfiable
 *     by construction; every cron call 401'd from the day it deployed.
 *
 * A string comparison has no such coupling. It is unaffected by the JWT
 * signing-key migration now underway on this project and by the deprecation of
 * `SUPABASE_ANON_KEY` / `SUPABASE_SERVICE_ROLE_KEY`.
 *
 * ⚠ THE SECRET IS THE ONLY GATE. Cron functions run `verify_jwt=false`, so
 * their URLs accept unauthenticated POSTs from anywhere and this comparison is
 * all that stands between the open internet and a privileged fan-out (push
 * sends, Gemini spend, storage deletion). `CRON_SECRET` must be long and
 * cryptographically random — `openssl rand -hex 32`. Never a memorable phrase.
 *
 * USAGE (per cron function)
 * -------------------------
 *   import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
 *
 *   Deno.serve(async (req) => {
 *     if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
 *     if (!await isAuthorizedCronCall(req)) {
 *       return new Response(JSON.stringify({ error: "Unauthorized" }), {
 *         status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 *       });
 *     }
 *     const logId = await logCronStart("<slug>");   // AFTER the gate — see below
 *     // ... handler body
 *   });
 *
 * ⚠ KEEP `logCronStart` AFTER THIS GATE. It is tempting to move it earlier so
 * that rejected calls leave a telemetry row — the 2026-07-26 batch considered
 * exactly that. Don't: on a `verify_jwt=false` endpoint it would hand every
 * anonymous caller an unauthenticated INSERT into `public.cron_call_log`.
 * Outage visibility is provided instead by `alert_cron_silence` (migration
 * 109), which alerts on the ABSENCE of successful runs and therefore needs no
 * writes from unauthenticated callers.
 */

/**
 * Constant-time string comparison.
 *
 * Both sides are hashed to a fixed 32-byte digest first, then compared with an
 * XOR-accumulate that always walks the full length. This leaks neither the
 * secret's length nor the position of the first differing byte, whereas a plain
 * `!==` short-circuits on the first mismatch and is measurable over enough
 * requests.
 *
 * Worth the few microseconds here specifically because this comparison is the
 * ONLY gate on 16 publicly-reachable endpoints (see the warning above), and the
 * secret in production is currently low-entropy by explicit accepted risk
 * (migration 107 header) — a weak secret plus a timing oracle is materially
 * worse than either alone.
 */
// Exported (review round 1 F11) so telegram-admin-bot's webhook-secret
// comparison — the ONLY gate on that publicly-reachable endpoint, same
// threat model as the 16+ cron-secret-gated endpoints this was written
// for — can reuse it instead of a bare `!==`.
export async function timingSafeEqual(a: string, b: string): Promise<boolean> {
  const enc = new TextEncoder();
  const [da, db] = await Promise.all([
    crypto.subtle.digest("SHA-256", enc.encode(a)),
    crypto.subtle.digest("SHA-256", enc.encode(b)),
  ]);
  const va = new Uint8Array(da);
  const vb = new Uint8Array(db);
  let diff = 0;
  for (let i = 0; i < va.length; i++) diff |= va[i] ^ vb[i];
  return diff === 0;
}

/**
 * True when the request carries `Authorization: Bearer <CRON_SECRET>`.
 *
 * False on a missing header, a malformed bearer, an unset `CRON_SECRET`, or any
 * mismatch. Never throws — safe to call without try/catch.
 */
export async function isAuthorizedCronCall(req: Request): Promise<boolean> {
  try {
    const authHeader = req.headers.get("Authorization") ?? "";
    if (!authHeader.startsWith("Bearer ")) {
      console.warn("[cron_auth] missing or malformed Authorization header");
      return false;
    }
    const token = authHeader.slice("Bearer ".length).trim();
    if (token.length === 0) {
      console.warn("[cron_auth] empty bearer token");
      return false;
    }

    // Trimmed on BOTH sides. A trailing newline pasted into the dashboard
    // secret would otherwise reject every call with no visible reason.
    const cronSecret = (Deno.env.get("CRON_SECRET") ?? "").trim();
    if (cronSecret.length === 0) {
      console.warn(
        "[cron_auth] CRON_SECRET is unset — every cron call will be rejected. " +
          "Set it in Project Settings -> Edge Functions -> Secrets, matching " +
          "the `cron_secret` Vault row exactly.",
      );
      return false;
    }

    if (!await timingSafeEqual(token, cronSecret)) {
      console.warn("[cron_auth] bearer token does not match CRON_SECRET");
      return false;
    }

    return true;
  } catch (err) {
    // Defensive — never let the auth gate crash its caller.
    console.error("[cron_auth] unexpected error:", err);
    return false;
  }
}

/*
 * HISTORY
 * -------
 * 2026-05-11 (7ad0c4)  Gate introduced; 8 cron functions were publicly callable.
 * 2026-05-12 (audit P0) Vault `service_role_key` row was empty, so the header
 *                       went out as `Bearer null` → 401 on every tick, 12 jobs.
 * 2026-05-15 (5a65bd)  Env-equality check broke on Vault/env key drift. That
 *                       write-up proposed "replace the brittle env-equality
 *                       check with a JWT signature+role decode" as the
 *                       permanent class fix.
 * 2026-05-16           The class fix shipped. It depended on
 *                       `SUPABASE_JWT_SECRET`, which cannot exist. The fix
 *                       made the bug permanent instead of ending it.
 * 2026-07-26 (c3f8a1)  Discovered: ~8 weeks of total cron silence. Three
 *                       safeguards had failed together — telemetry sat behind
 *                       the failing gate, pg_cron reports `succeeded` for any
 *                       dispatch regardless of HTTP status, and the health
 *                       alert computed a rate from the table the failure kept
 *                       empty. Replaced with this shared-secret gate; the
 *                       `deno.land/x/jose` dependency is gone with it, closing
 *                       a remote-dep-rot risk this repo has already been bitten
 *                       by (feedback_mistake_remote_dep_rot).
 */

/**
 * cron_telemetry — per-invocation execution telemetry for cron Edge Functions.
 *
 * Closes audit 2026-05-17 / OI-15. Background: `cron.job_run_details.status='succeeded'`
 * only confirms the pg_cron-side `net.http_post()` dispatch succeeded; it does NOT
 * reflect the Edge Function's actual HTTP response. During the Vault drift incident
 * (2026-05-11..16 — retired root §19 entry #161, relocated to
 * `supabase/functions/CLAUDE.md`'s cron-auth pattern by the 2026-05-18 declutter),
 * pg_cron reported 1066 "succeeded" runs across a week while every single call returned
 * 401 server-side and zero work happened.
 *
 * Each cron Edge Function imports this helper and:
 *   1. Calls `logCronStart(name)` at the top of its `serve` handler → returns a row id.
 *   2. Calls `logCronEnd(id, status, httpStatus?, errorSummary?)` before returning.
 *
 * The row lands in `public.cron_call_log` (migration 068). Retention: 10 days (migration
 * 169), plus each function's newest success and newest row for good (migration 172), via
 * `public.cleanup_cron_call_log()`, which `db_maintenance_nightly` calls (069, 141, 144).
 *
 * Failures inside the telemetry call itself are SWALLOWED (try/catch + debug log).
 * Cron functions MUST NOT 500 because telemetry is broken.
 */

import { createClient, SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL") ?? "";
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";

type CronLogStatus = "success" | "failed";

let _adminClient: SupabaseClient | null = null;

function adminClient() {
  if (_adminClient) return _adminClient;
  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
    // Edge runtime quirk — should never happen in prod, but don't crash if it does.
    return null;
  }
  _adminClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
  return _adminClient;
}

/**
 * Insert a `started` row. Returns the row id so the caller can update on exit.
 *
 * Returns `null` if telemetry insert fails — callers should pass that null straight
 * back into `logCronEnd` (which is a no-op on null id). The function itself never
 * throws.
 */
export async function logCronStart(functionName: string): Promise<number | null> {
  try {
    const supabase = adminClient();
    if (!supabase) return null;
    const { data, error } = await supabase
      .from("cron_call_log")
      .insert({ function_name: functionName, status: "started" })
      .select("id")
      .single();
    if (error || !data) {
      console.warn(`[cron_telemetry] start insert failed for ${functionName}`, error);
      return null;
    }
    return (data as { id: number }).id;
  } catch (e) {
    console.warn(`[cron_telemetry] start exception for ${functionName}`, e);
    return null;
  }
}

/**
 * Update the row created by `logCronStart` with terminal status.
 *
 * Passes-through silently when `id` is null (i.e. start insert failed).
 */
export async function logCronEnd(
  id: number | null,
  status: CronLogStatus,
  opts?: { httpStatus?: number; requestId?: string; errorSummary?: string },
): Promise<void> {
  if (id == null) return;
  try {
    const supabase = adminClient();
    if (!supabase) return;
    const patch: Record<string, unknown> = { status };
    if (opts?.httpStatus !== undefined) patch.http_status = opts.httpStatus;
    if (opts?.requestId) patch.request_id = opts.requestId;
    if (opts?.errorSummary) {
      // Cap error summary at 1000 chars to avoid bloat from giant stack traces.
      patch.error_summary = opts.errorSummary.slice(0, 1000);
    }
    const { error } = await supabase
      .from("cron_call_log")
      .update(patch)
      .eq("id", id);
    if (error) {
      console.warn(`[cron_telemetry] end update failed for id=${id}`, error);
    }
  } catch (e) {
    console.warn(`[cron_telemetry] end exception for id=${id}`, e);
  }
}

// supabase/functions/_shared/revenuecat_mirror.ts
//
// OI-519 (+51), plan docs/plans/2026-11-23-revenuecat-play-billing-51.md section 4. The ONE place that turns a RevenueCat
// customer into our `subscriptions` row. Every trigger (revenuecat-webhook, revenuecat-sync, revenuecat-reconcile) calls
// mirrorRevenueCatCustomer(uid): it re-reads the truth from RevenueCat's REST API with the secret key and upserts through
// public.upsert_play_subscription (migration 182). Nothing from a webhook body or the phone is ever written.
//
// One Play row per user: RevenueCat REST v1 keys `subscriber.subscriptions` by the Google subscription id WITHOUT the
// base-plan suffix (`avya_pro`) and returns the base plan in `product_plan_identifier` (plan section 18, U0).
//
// Log safety (payment-log-safety contract): this module never logs a request or response body, a key, or a user id.

import { pgErrorCode } from "./payment_log_safe.ts";
import { isEnvExactlyTrue, type EnvReader } from "./subscription_stacking.ts";

export const MIRROR_ENABLE_ENV = "ENABLE_PLAY_BILLING_MIRROR";
export const REVENUECAT_SECRET_ENV = "REVENUECAT_SECRET_KEY";
export const REVENUECAT_API_BASE = "https://api.revenuecat.com/v1";
/** The Google Play subscription id (RevenueCat REST key, no base-plan suffix). */
export const PLAY_SUBSCRIPTION_ID = "avya_pro";
/** A renewing row stays active this long past the store expiry while the renewal is posted (plan section 4 rule 2). */
export const PLAY_RENEWAL_WINDOW_MS = 3 * 60 * 60 * 1000;
export const REVENUECAT_TIMEOUT_MS = 10_000;
export const UNKNOWN_PRODUCT_ALERT_SOURCE = "revenuecat_unknown_product";
/** A running Play row whose customer read shows no avya_pro Play entry (hermes seat 1). */
export const ENTRY_MISSING_ALERT_SOURCE = "revenuecat_entry_missing";
/** The secret REST key is unset while the switch is on: every read fails, so nobody gets PRO from Play (B-pass F2). */
export const SECRET_MISSING_ALERT_SOURCE = "revenuecat_secret_missing";

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export function isMirrorEnabled(env?: EnvReader): boolean {
  return env ? isEnvExactlyTrue(MIRROR_ENABLE_ENV, env) : isEnvExactlyTrue(MIRROR_ENABLE_ENV);
}

export function isUuid(v: unknown): v is string {
  return typeof v === "string" && UUID_RE.test(v);
}

export type PlayPlan = "monthly" | "yearly";
export type PlayStatus = "active" | "expired" | "cancelled";

export type PlayRow = {
  productId: string;
  plan: PlayPlan;
  status: PlayStatus;
  startIso: string;
  endIso: string;
  autoRenew: boolean;
  environment: "SANDBOX" | "PRODUCTION";
  originalTxn: string | null;
  storeExpiresIso: string;
};

export type MapIssue = { kind: "unknown_product" | "unknown_plan" | "bad_entry"; productId: string };

function parseMs(v: unknown): number | null {
  if (typeof v !== "string" || v.length === 0) return null;
  const ms = Date.parse(v);
  return Number.isFinite(ms) ? ms : null;
}

function iso(ms: number): string {
  return new Date(ms).toISOString();
}

/**
 * Pure. Maps a RevenueCat REST v1 customer (`GET /v1/subscribers/{id}` body) to our Play rows at instant `nowMs`.
 * Rules, first match wins (plan section 4):
 *   1. refunded: refunded_at >= P (the latest period's purchase_date)  -> cancelled, end = refunded_at
 *   2. renewing: no unsubscribe, no billing issue, not paused          -> active iff E + 3 h > now, end = E + 3 h
 *   3. otherwise: effective end = max(E, G)                           -> active iff > now, else expired
 * Always: store_expires_at = E, start = P, environment from is_sandbox.
 */
export function mapCustomerToRows(customer: unknown, nowMs: number): { rows: PlayRow[]; issues: MapIssue[] } {
  const rows: PlayRow[] = [];
  const issues: MapIssue[] = [];
  const subs = (customer as { subscriber?: { subscriptions?: unknown } } | null)?.subscriber?.subscriptions;
  if (!subs || typeof subs !== "object") return { rows, issues };

  for (const [productId, raw] of Object.entries(subs as Record<string, unknown>)) {
    const e = raw as Record<string, unknown> | null;
    if (!e || typeof e !== "object" || e.store !== "play_store") continue; // other stores are not ours to mirror
    if (productId !== PLAY_SUBSCRIPTION_ID) {
      issues.push({ kind: "unknown_product", productId });
      continue;
    }
    const plan = e.product_plan_identifier;
    if (plan !== "monthly" && plan !== "yearly") {
      issues.push({ kind: "unknown_plan", productId });
      continue;
    }
    const P = parseMs(e.purchase_date);
    const E = parseMs(e.expires_date);
    if (P === null || E === null || typeof e.is_sandbox !== "boolean") {
      issues.push({ kind: "bad_entry", productId });
      continue;
    }
    const refundedAt = parseMs(e.refunded_at);
    const unsubscribed = e.unsubscribe_detected_at != null;
    const billingIssue = e.billing_issues_detected_at != null;
    const paused = e.auto_resume_date != null;
    const renewing = !unsubscribed && !billingIssue && !paused;

    let status: PlayStatus;
    let endMs: number;
    if (refundedAt !== null && refundedAt >= P) {
      status = "cancelled";
      endMs = refundedAt;
    } else if (renewing) {
      endMs = E + PLAY_RENEWAL_WINDOW_MS;
      status = endMs > nowMs ? "active" : "expired";
    } else {
      const G = billingIssue ? parseMs(e.grace_period_expires_date) : null;
      endMs = G !== null && G > E ? G : E;
      status = endMs > nowMs ? "active" : "expired";
    }

    const txn = e.store_transaction_id;
    rows.push({
      productId,
      plan,
      status,
      startIso: iso(P),
      endIso: iso(endMs),
      autoRenew: renewing,
      environment: e.is_sandbox ? "SANDBOX" : "PRODUCTION",
      originalTxn: typeof txn === "string" || typeof txn === "number" ? String(txn) : null,
      storeExpiresIso: iso(E),
    });
  }
  return { rows, issues };
}

// ------------------------------------------------------------------------------------------------------------------
// IO
// ------------------------------------------------------------------------------------------------------------------

/** `sandbox_refused`: a SANDBOX read was not allowed to replace a running PRODUCTION row (migration 182, B-pass F1). */
export type UpsertResult = "written" | "stale_read" | "sandbox_refused";

export type MirrorDb = {
  userExists(uid: string): Promise<boolean>;
  upsertPlayRow(uid: string, row: PlayRow, readAtIso: string): Promise<UpsertResult>;
  alert(source: string, severity: "warn" | "critical", summary: string, context: Record<string, unknown>): Promise<void>;
  /** Whether the user holds an `active` Play row. Optional: absent = the entry-missing check is skipped. */
  hasActivePlayRow?(uid: string): Promise<boolean>;
};

export type MirrorDeps = {
  db: MirrorDb;
  secretKey: string | undefined;
  fetchFn?: typeof fetch;
  nowMs?: () => number;
  timeoutMs?: number;
};

export type MirrorOutcome =
  | { outcome: "mirrored"; rows: { productId: string; status: PlayStatus; result: UpsertResult }[]; mapped: PlayRow[] }
  | { outcome: "refused_uid" | "unknown_user" };

export class RevenueCatReadError extends Error {
  constructor(public readonly code: string) {
    super(`revenuecat read failed: ${code}`);
    this.name = "RevenueCatReadError";
  }
}

/** PURE. Text from RevenueCat's body for a jsonb field: at most [n] characters, no control or line-separator or
 *  format characters (replaced by "?"), never quoted (B-pass on the hermes fixes, seat A: `boundedText` adds quotes). */
export function plainBounded(v: unknown, n: number): string {
  return String(v).slice(0, n).replace(/[\u0000-\u001f\u007f-\u009f\u2028\u2029\u200b-\u200f\u202a-\u202e\u2060-\u2064\ufeff]/g, "?");
}

export const RETRY_429_DEFAULT_WAIT_MS = 500;
export const RETRY_429_MAX_WAIT_MS = 2000;

/** One GET with a timeout; one retry on 5xx / 429 / network error (a 429 waits first). Returns the parsed body. */
export async function fetchRevenueCatCustomer(
  uid: string,
  secretKey: string,
  fetchFn: typeof fetch = fetch,
  timeoutMs = REVENUECAT_TIMEOUT_MS,
  sleepFn: (ms: number) => Promise<void> = (ms) => new Promise((r) => setTimeout(r, ms)),
): Promise<unknown> {
  let lastCode = "unknown";
  for (let attempt = 1; attempt <= 2; attempt++) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    try {
      const res = await fetchFn(`${REVENUECAT_API_BASE}/subscribers/${encodeURIComponent(uid)}`, {
        method: "GET",
        headers: { Authorization: `Bearer ${secretKey}`, Accept: "application/json" },
        signal: ctrl.signal,
      });
      if (res.status === 200 || res.status === 201) {
        return await res.json();
      }
      await res.body?.cancel();
      lastCode = `http_${res.status}`;
      if (!(res.status >= 500 || res.status === 429)) break; // a 4xx other than 429 will not get better
      if (res.status === 429 && attempt === 1) {
        // An immediate retry of a 429 is a second 429: wait Retry-After (seconds), bounded (hermes seat 2).
        const ra = Number(res.headers.get("Retry-After") ?? "");
        await sleepFn(Number.isFinite(ra) && ra > 0 ? Math.min(ra * 1000, RETRY_429_MAX_WAIT_MS) : RETRY_429_DEFAULT_WAIT_MS);
      }
    } catch (e) {
      lastCode = (e as { name?: string })?.name === "AbortError" ? "timeout" : "network";
    } finally {
      clearTimeout(timer);
    }
  }
  throw new RevenueCatReadError(lastCode);
}

/**
 * Re-reads the customer from RevenueCat and upserts the Play row(s). Refuses a uid that is not a UUID or has no users row
 * BEFORE any RevenueCat call (a GET creates a missing customer). `read_at` is stamped BEFORE the GET is issued, so a slower,
 * older read can never overwrite a newer one (the upsert's ordering guard). Throws RevenueCatReadError on a failed read and
 * lets a database error propagate: the caller answers 5xx so the trigger is retried. A missing secret key is a failed read
 * too (code `no_secret`, after a critical alert): an answer of "nothing to do" would let a paying user silently stay free.
 */
export async function mirrorRevenueCatCustomer(uid: string, deps: MirrorDeps): Promise<MirrorOutcome> {
  if (!isUuid(uid)) return { outcome: "refused_uid" };
  if (!deps.secretKey) {
    try {
      await deps.db.alert(SECRET_MISSING_ALERT_SOURCE, "critical", "REVENUECAT_SECRET_KEY is unset while the Play mirror is on: no Play purchase can be confirmed", {});
    } catch (_) { /* the typed throw below must win over any alert failure (B-pass round 2, F1) */ }
    throw new RevenueCatReadError("no_secret");
  }
  if (!(await deps.db.userExists(uid))) return { outcome: "unknown_user" };

  const now = deps.nowMs ?? Date.now;
  const readAtIso = iso(now());
  const customer = await fetchRevenueCatCustomer(uid, deps.secretKey, deps.fetchFn ?? fetch, deps.timeoutMs);
  const { rows, issues } = mapCustomerToRows(customer, now());

  for (const issue of issues) {
    await deps.db.alert(
      UNKNOWN_PRODUCT_ALERT_SOURCE,
      "critical",
      `RevenueCat returned a Play subscription the mirror does not know (${issue.kind}); no row was written`,
      // productId comes from RevenueCat's body: bounded and escaped before it is stored (hermes seat 4).
      { kind: issue.kind, product_id: plainBounded(issue.productId, 64) },
    );
  }

  const out: { productId: string; status: PlayStatus; result: UpsertResult }[] = [];
  for (const row of rows) {
    const result = await deps.db.upsertPlayRow(uid, row, readAtIso);
    if (result === "sandbox_refused") {
      // A license tester's SANDBOX read met a running PRODUCTION row (migration 182 keeps the PRODUCTION row). Rare: say so.
      console.warn("[revenuecat-mirror] upsert result=sandbox_refused (a SANDBOX read was not allowed over PRODUCTION)");
    }
    out.push({ productId: row.productId, status: row.status, result });
  }
  // A good read with NO avya_pro Play entry while our Play row still grants PRO: nothing writes that row (the mirror
  // never revokes on an absence: a missing entry can be a RevenueCat-side oddity, and a wrong revoke takes PRO from a
  // payer). The founder checks it by hand (hermes seat 1, 2026-11-24).
  // Diagnostic only: its read or alert failing must never turn a good mirror into a failed one (B-pass on the hermes
  // fixes, seat A). One open alert per source per day (the shared `alert` dedup): the summary says how to find the rest.
  if (rows.length === 0 && issues.length === 0 && deps.db.hasActivePlayRow) {
    try {
      if (await deps.db.hasActivePlayRow(uid)) {
        await deps.db.alert(
          ENTRY_MISSING_ALERT_SOURCE,
          "critical",
          "A Play row grants PRO but RevenueCat shows no Play subscription for this customer: check it by hand " +
            "(one alert per day; others may exist: compare every active Play row with RevenueCat)",
          { user_id: uid },
        );
      }
    } catch (e) {
      console.warn(`[revenuecat-mirror] entry-missing check failed (ignored) code=${pgErrorCode(e)}`);
    }
  }
  return { outcome: "mirrored", rows: out, mapped: rows };
}

// ------------------------------------------------------------------------------------------------------------------
// Supabase adapter (service-role client)
// ------------------------------------------------------------------------------------------------------------------

// deno-lint-ignore no-explicit-any
export type ServiceClient = { from: (t: string) => any; rpc: (fn: string, args: Record<string, unknown>) => any };

export function supabaseMirrorDb(client: ServiceClient): MirrorDb {
  return {
    async userExists(uid) {
      const { data, error } = await client.from("users").select("id").eq("id", uid).maybeSingle();
      if (error) throw new Error(`users read failed: ${(error as { code?: string }).code ?? "unknown"}`);
      return !!data;
    },
    async hasActivePlayRow(uid) {
      const { data, error } = await client.from("subscriptions").select("id").eq("user_id", uid).eq("store", "play")
        .eq("status", "active").limit(1);
      if (error) throw new Error(`play row read failed: ${(error as { code?: string }).code ?? "unknown"}`);
      return Array.isArray(data) && data.length > 0;
    },
    async upsertPlayRow(uid, row, readAtIso) {
      // oi79-ok: the function RETURNS text (one scalar: 'written', 'stale_read' or 'sandbox_refused'); any other answer throws below.
      const { data, error } = await client.rpc("upsert_play_subscription", {
        p_user_id: uid,
        p_product_id: row.productId,
        p_plan: row.plan,
        p_status: row.status,
        p_start: row.startIso,
        p_end: row.endIso,
        p_auto_renew: row.autoRenew,
        p_environment: row.environment,
        p_original_txn: row.originalTxn,
        p_store_expires_at: row.storeExpiresIso,
        p_read_at: readAtIso,
      });
      if (error) throw new Error(`upsert_play_subscription failed: ${(error as { code?: string }).code ?? "unknown"}`);
      if (data !== "written" && data !== "stale_read" && data !== "sandbox_refused") {
        throw new Error("upsert_play_subscription returned an unknown value");
      }
      return data;
    },
    async alert(source, severity, summary, context) {
      try {
        const since = new Date(Date.now() - 23 * 3600 * 1000).toISOString();
        const { data, error: readErr } = await client.from("alerts").select("id").eq("source", source).eq("acknowledged", false)
          .gte("detected_at", since).limit(1);
        if (readErr) {
          // An unreadable dedup must not become one alert per call (up to ~220 a reconcile run): say so and send none.
          console.error(`[revenuecat_mirror] alert dedup read failed for source=${source} code=${pgErrorCode(readErr)}`);
          return;
        }
        if (Array.isArray(data) && data.length > 0) return; // one open alert per source per day
        const { error } = await client.from("alerts").insert({ source, severity, summary, context_json: context });
        if (error) console.error(`[revenuecat_mirror] alert insert failed for source=${source} code=${pgErrorCode(error)}`);
      } catch (_) {
        console.error(`[revenuecat_mirror] alert insert failed for source=${source}`);
      }
    },
  };
}

// _shared/payment_log_safe.ts — what a payment-path log line may carry (OI-360, payment-hardening U0).
//
// The payment functions used to log whole objects: a PostgREST error (its `details` echoes the failing
// row, e.g. a Razorpay signature), a Razorpay error body, the payment notes, the raw request `plan`.
// Platform logs are kept and readable by every dashboard user, so a log line must carry only what an
// operator needs to act: a short error CODE, a type name, the SHAPE of the notes, and client-supplied
// text bounded and quoted so it can neither grow the line nor forge a second one.
//
// Pure: no imports, no I/O. Tests: payment_log_safe_test.ts.

/** A value that is already a code (`23505`, `bad_rpc_response`, an Error name) when it is a short plain token; else `no_code`. */
export function codeToken(v: unknown): string {
  return typeof v === "string" && /^[A-Za-z0-9_]{1,24}$/.test(v) ? v : "no_code";
}

/** The PostgREST / Postgres error code (`23505`, `PGRST116`) when it is a short plain token; else `no_code`. Never details, hint or message. */
export function pgErrorCode(err: unknown): string {
  if (err === null || typeof err !== "object") return "no_code";
  const code = (err as { code?: unknown }).code;
  return typeof code === "string" && /^[A-Za-z0-9_]{1,16}$/.test(code) ? code : "no_code";
}

/** An Error's `name` (never its message, which can carry a URL or a token); otherwise the value's type. */
export function errorName(err: unknown): string {
  if (err instanceof Error) return err.name;
  return err === null ? "null" : typeof err;
}

// JSON.stringify escapes the C0 controls (newline, ESC) but leaves DEL, the C1 range (NEL among them), the
// Unicode line and paragraph separators and the format characters (bidi overrides, zero-width marks) raw: a log
// viewer can break a line on the first ones and visually reorder or hide text with the others.
const UNESCAPED_LINE_BREAKS = /[\u007f-\u009f\u2028\u2029\p{Cf}]/gu;
/** Every character a frame may not carry raw: the C0 controls as well, since a frame is not JSON-quoted. */
const FRAME_UNSAFE = /[\u0000-\u001f\u007f-\u009f\u2028\u2029\p{Cf}]/gu;

/**
 * Up to [n] stack frames of a thrown Error (`at fn (file:line:col)`), joined by " | ", each escaped and at most
 * 200 characters, WITHOUT the message: a SyntaxError from `req.json()` quotes the request body in its message, and
 * that text can hold a newline followed by "at ", so the stack is read only AFTER the end of the message (B-pass
 * bfaeb6fb79da finding 1). A non-empty message the stack does not contain gives `no_stack` (fail closed), as does
 * an error without frames.
 */
export function stackFrames(err: unknown, n = 3): string {
  // Called inside the catch-alls, so it never throws (a throwing `stack` or `message` getter is `no_stack`), and a
  // non-string message is `no_stack`: its text in the stack header cannot be located (B-pass aabb2b0dbdbb).
  try {
    if (!(err instanceof Error)) return "no_stack";
    const stack: unknown = err.stack;
    const msg: unknown = err.message;
    if (typeof stack !== "string" || typeof msg !== "string") return "no_stack";
    const at = msg === "" ? 0 : stack.indexOf(msg);
    if (at < 0) return "no_stack";
    const frames = stack.slice(at + msg.length).split("\n").map((l) => l.trim()).filter((l) => l.startsWith("at "))
      .slice(0, n)
      .map((l) => l.slice(0, 200).replace(FRAME_UNSAFE, (c) => "\\u" + c.charCodeAt(0).toString(16).padStart(4, "0")));
    return frames.length > 0 ? frames.join(" | ") : "no_stack";
  } catch {
    return "no_stack";
  }
}

/** A client- or upstream-supplied value as a quoted, escaped string of at most `n` characters of the value. */
export function boundedText(v: unknown, n = 40): string {
  return JSON.stringify(String(v).slice(0, n))
    .replace(UNESCAPED_LINE_BREAKS, (c) => "\\u" + c.charCodeAt(0).toString(16).padStart(4, "0"));
}

/**
 * A non-2xx Razorpay answer: the status, plus `error.code` and `error.reason` when each is a string (each
 * bounded). Never the description, the field names or anything else from the body.
 */
export function razorpayErrorSummary(status: unknown, bodyText: unknown): string {
  const s = typeof status === "number" && Number.isInteger(status) ? String(status) : "?";
  let parsed: unknown = null;
  try {
    parsed = JSON.parse(String(bodyText));
  } catch {
    return `status=${s}`;
  }
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) return `status=${s}`;
  const e = (parsed as { error?: unknown }).error;
  if (e === null || typeof e !== "object" || Array.isArray(e)) return `status=${s}`;
  const parts = [`status=${s}`];
  const code = (e as { code?: unknown }).code;
  const reason = (e as { reason?: unknown }).reason;
  if (typeof code === "string") parts.push(`code=${boundedText(code.slice(0, 40))}`);
  if (typeof reason === "string") parts.push(`reason=${boundedText(reason.slice(0, 40))}`);
  return parts.join(" ");
}

/** The note keys an app order writes (create-razorpay-order) or Razorpay is known to add. */
const KNOWN_NOTE_KEYS = ["user_id", "plan", "promo_code", "stacks_after", "source", "billing_cycle"] as const;

/**
 * The SHAPE of Razorpay payment notes: which known keys are present, plus how many other keys. Never a value,
 * never an unknown key's name. Razorpay sends `[]` for empty notes; an array, null or a primitive is reported
 * by its type.
 */
export function notesShape(notes: unknown): string {
  if (notes === null) return "null";
  if (Array.isArray(notes)) return `array(${notes.length})`;
  if (typeof notes !== "object") return typeof notes;
  const keys = Object.keys(notes as Record<string, unknown>);
  const known = KNOWN_NOTE_KEYS.filter((k) => keys.includes(k));
  const other = keys.filter((k) => !(KNOWN_NOTE_KEYS as readonly string[]).includes(k)).length;
  return `keys=[${known.join(",")}] other=${other}`;
}

/**
 * subscription_stacking - PRO time stacks AFTER the current PRO end (OI-341).
 *
 * `verify-payment` and `razorpay-webhook` insert the paid `subscriptions` row.
 * Piece A (docs/plans/oi341-purchase-in-trial.md) put the stacked end date
 * behind the enabling secret below; Piece B1 (docs/plans/oi341-piece-b-door.md)
 * replaced Piece A's ON path (a read, then an insert: two requests, nothing
 * serialising them per user) with ONE call to the Postgres function
 * `public.record_paid_subscription` (migration 161), which takes the per-user
 * lock shared with the referral redeem and job, checks idempotency, computes
 * `max(now, latest active end) + days` and inserts, in one transaction.
 * `start_date` stays the payment time on purpose: the referral reward job
 * (migration 159) reads it as the payment time.
 *
 * DARK BY DEFAULT (CLAUDE.md 4.6 / 4.12.4): unless the enabling secret
 * `ENABLE_SUBSCRIPTION_STACKING` is exactly the string "true", the writers run
 * their OFF branch: today's insert with `plainEndDate(now, days)`, no extra
 * query and no call to the function.
 *
 * Catastrophic tier (a payment-path module): see docs/blast_radius.yaml.
 */

/** The enabling secret. Strictly the string "true"; read per call, never at load. */
export const STACKING_ENABLE_ENV = "ENABLE_SUBSCRIPTION_STACKING";

/** A Razorpay payment id: the only shape either writer accepts. */
const PAYMENT_ID_RE = /^pay_[A-Za-z0-9]{1,64}$/;

export function isValidPaymentId(id: unknown): id is string {
  return typeof id === "string" && PAYMENT_ID_RE.test(id);
}

export type EnvReader = (name: string) => string | undefined;

const defaultEnv: EnvReader = (name) => Deno.env.get(name);

/**
 * The ONE switch rule for every payment secret: the variable is exactly the
 * string "true". " true", "TRUE", "1" and absent are all OFF (OI-341 Piece B2a,
 * plan 2.1), so the two switches below cannot drift to different readings.
 */
export function isEnvExactlyTrue(name: string, env: EnvReader = defaultEnv): boolean {
  return env(name) === "true";
}

/** The writers' stacking switch. */
export function isStackingEnabled(env: EnvReader = defaultEnv): boolean {
  return isEnvExactlyTrue(STACKING_ENABLE_ENV, env);
}

/**
 * The purchase door's switch (`create-razorpay-order`, OI-341 Piece B2a plan
 * 2.2): a `referral_trial` user may create an order only when this AND
 * `isStackingEnabled` are on in the door's own isolate.
 */
export const TRIAL_PURCHASE_ENABLE_ENV = "ENABLE_TRIAL_PURCHASE";

export function isTrialPurchaseEnabled(env: EnvReader = defaultEnv): boolean {
  return isEnvExactlyTrue(TRIAL_PURCHASE_ENABLE_ENV, env);
}

/**
 * The OFF-branch end date: `now + days` with the SAME `setDate(getDate() + days)`
 * the writers used inline before Piece A, so the OFF output is byte-identical to
 * `origin/main` (pinned by the golden recordings in each writer's tests).
 */
export function plainEndDate(now: Date, days: number): Date {
  const end = new Date(now);
  end.setDate(end.getDate() + days);
  return end;
}

/** Minimal structural view of the supabase-js client the ON path uses. */
// deno-lint-ignore no-explicit-any
export type RecordDb = { rpc: (fn: string, args: Record<string, unknown>) => any };

export type RecordArgs = {
  userId: string;
  plan: string;
  paymentId: string;
  /** A Razorpay entity can omit order_id; undefined is sent as JSON null (an omitted key would make PostgREST miss the 5-arg function). */
  orderId: string | null | undefined;
  signature: string;
};

export type RecordResult =
  | { ok: true; endDate: Date; startDate: Date; inserted: boolean }
  | { ok: false; code: string };

function parseInstant(raw: unknown): Date | null {
  if (typeof raw !== "string") return null;
  const d = new Date(raw);
  return Number.isNaN(d.getTime()) ? null : d;
}

/**
 * The ON path: one call to `public.record_paid_subscription`. Returns `ok:false`
 * on a database error (its SQLSTATE, or `read_error` for a transport failure
 * that postgrest-js reports with an empty code), on a thrown rejection, and on a
 * malformed answer (not a one-row array, or an end/start that does not parse):
 * `bad_rpc_response`, so a missing route or a scalar answer never reads as
 * success.
 */
export async function recordPaidSubscription(
  db: RecordDb,
  args: RecordArgs,
): Promise<RecordResult> {
  try {
    // oi79-ok: the function returns exactly one row by construction (RETURN QUERY once per path); a non-one-row answer is bad_rpc_response below.
    const { data, error } = await db.rpc("record_paid_subscription", {
      p_user_id: args.userId,
      p_plan: args.plan,
      p_payment_id: args.paymentId,
      p_order_id: args.orderId ?? null,
      p_signature: args.signature,
    });
    if (error) {
      // `||`, not `??`: postgrest-js reports a transport failure with code "".
      const code = (error as { code?: string }).code || "read_error";
      return { ok: false, code: String(code) };
    }
    if (!Array.isArray(data) || data.length !== 1) {
      return { ok: false, code: "bad_rpc_response" };
    }
    const row = data[0] as {
      out_end_date?: unknown;
      out_start_date?: unknown;
      out_inserted?: unknown;
    };
    const endDate = parseInstant(row.out_end_date);
    const startDate = parseInstant(row.out_start_date);
    if (endDate === null || startDate === null || typeof row.out_inserted !== "boolean") {
      return { ok: false, code: "bad_rpc_response" };
    }
    return { ok: true, endDate, startDate, inserted: row.out_inserted };
  } catch (e) {
    return { ok: false, code: (e as { name?: string })?.name ?? "thrown" };
  }
}

// revenuecat-reconcile/logic.ts — OI-519 (+51), plan section 4 entry point 3 and item 4 (the referral defer drain).
//
// Hourly cron (cron_auth + cron_telemetry). Order of a run:
//   1. Stall alert FIRST, even with the switch OFF: deferral rows pending > 24 h, in flight > 2 h, or needs_check.
//   2. Switch OFF -> stop (nothing read from RevenueCat, nothing written).
//   3. Crashed claims: an in_flight row older than 1 h -> needs_check (never re-sent).
//   4. Drain the 20 oldest pending deferrals: fresh read per row; active with a future store expiry -> claim (CAS) ->
//      POST defer; no Play entitlement -> fall back to ordinary days; anything else (renewal window, grace, read error)
//      -> stays pending. A defer whose outcome is unknown is NEVER re-sent and NEVER auto-confirmed (plan v7). One row's
//      error is counted and the next row is tried (B-pass F4); a row that fails after its claim stays in_flight, so step 3
//      of a later run moves it to needs_check.
//   5. Reconcile: re-mirror every user whose Play row ends within [now - 3 d, now + 1 d] or is active and was last read
//      more than 24 h ago (bounded), so renewals, expiries and refunds land even when every webhook retry failed.
// Steps 4 and 5 share one time budget (RUN_BUDGET_MS, B-pass F3): a slow RevenueCat cannot run the function into the
// platform's wall-clock limit (no telemetry end, no drain). The drain goes first, so referral days are never starved by
// the reconcile list. A run whose reconcile reads ALL failed, or whose drain had an error, ends `failed` (B-pass F9).

import { errorName } from "../_shared/payment_log_safe.ts";
import { type MirrorOutcome, PLAY_SUBSCRIPTION_ID, RevenueCatReadError } from "../_shared/revenuecat_mirror.ts";

export const FN_NAME = "revenuecat-reconcile";
export const DRAIN_BATCH = 20;
/** Steps 4 and 5 start no new row or user after this long (one row can still take ~50 s: two reads and a POST). */
export const RUN_BUDGET_MS = 60_000;
export const STALL_ALERT_SOURCE = "store_reward_deferrals_stalled";
export const NEEDS_CHECK_ALERT_SOURCE = "store_reward_needs_check";
/** The drain used the whole budget and no reconcile read ran (B-pass round 2, F3). */
export const RECONCILE_STARVED_ALERT_SOURCE = "revenuecat_reconcile_starved";

export type DeferralRow = { id: string; user_id: string; days: number };
export type MarkStatus = "applied" | "needs_check" | "pending";

/** How far back a webhook answered while the switch was OFF is caught up (hermes seat 4, 2026-11-24). */
export const SWITCH_OFF_CATCH_UP_DAYS = 7;

/**
 * PURE. Users whose latest `switch_off` webhook (the switch was OFF, so nothing was mirrored and RevenueCat was told 200,
 * so it never retries) is NEWER than their latest Play read: their purchase or change was never mirrored. A user with no
 * Play row at all is included. Order: most recent event first.
 */
export function switchOffCatchUpUids(
  events: { user_id: string | null; received_at: string }[],
  reads: { user_id: string; store_read_at: string | null }[],
): string[] {
  const lastEvent = new Map<string, number>();
  for (const e of events) {
    if (!e.user_id) continue;
    const t = Date.parse(e.received_at);
    if (Number.isFinite(t) && t > (lastEvent.get(e.user_id) ?? -Infinity)) lastEvent.set(e.user_id, t);
  }
  const lastRead = new Map<string, number>();
  for (const r of reads) {
    const t = r.store_read_at ? Date.parse(r.store_read_at) : NaN;
    if (Number.isFinite(t) && t > (lastRead.get(r.user_id) ?? -Infinity)) lastRead.set(r.user_id, t);
  }
  return [...lastEvent.entries()]
    .filter(([uid, t]) => !(lastRead.has(uid) && lastRead.get(uid)! >= t))
    .sort((a, b) => b[1] - a[1])
    .map(([uid]) => uid);
}

/** At most this many catch-up users per run, read AFTER the regular candidates (B-pass on the hermes fixes, seat A: a
 *  user whose read writes nothing stays a catch-up candidate for the whole window and must not crowd out the rest). */
export const SWITCH_OFF_CATCH_UP_MAX = 50;

/** PURE. The run's re-read list: the regular candidates first (deduplicated, in order), then at most
 *  [SWITCH_OFF_CATCH_UP_MAX] catch-up users not already listed. */
export function mergeReconcileCandidates(regular: readonly string[], catchUp: readonly string[]): string[] {
  const out = [...new Set(regular)];
  const seen = new Set(out);
  let added = 0;
  for (const uid of catchUp) {
    if (added >= SWITCH_OFF_CATCH_UP_MAX) break;
    if (seen.has(uid)) continue;
    seen.add(uid);
    out.push(uid);
    added++;
  }
  return out;
}

export type ReconcileDb = {
  stallCounts: (nowMs: number) => Promise<{ pendingOld: number; inFlightOld: number; needsCheck: number }>;
  reconcileUids: (nowMs: number) => Promise<string[]>;
  crashedInFlight: (nowMs: number) => Promise<{ id: string; token: string }[]>;
  /** Pending rows, least recently looked at first (updated_at, then created_at). */
  pendingRows: (limit: number) => Promise<DeferralRow[]>;
  /** Marks a pending row as looked at (updated_at = now), so rows that keep waiting rotate behind the others. */
  touch: (id: string) => Promise<void>;
  claim: (id: string) => Promise<string | null>;
  mark: (id: string, token: string, status: MarkStatus) => Promise<boolean>;
  fallBack: (id: string, token: string | null) => Promise<string>;
};

export type ReconcileDeps = {
  authorized: (req: Request) => Promise<boolean>;
  telemetryStart: () => Promise<number | null>;
  telemetryEnd: (id: number | null, status: "success" | "failed", opts: { httpStatus: number; errorSummary?: string }) => Promise<void>;
  mirrorEnabled: () => boolean;
  db: ReconcileDb;
  mirror: (uid: string) => Promise<MirrorOutcome>;
  postDefer: (uid: string, days: number) => Promise<number>;
  alert: (source: string, summary: string, context: Record<string, unknown>) => Promise<void>;
  nowMs?: () => number;
};

export type Decision = "claim" | "fall_back" | "wait" | "skip";

/** Pure: what to do with a pending deferral given a fresh mirror of the user. */
export function decide(out: MirrorOutcome, nowMs: number): Decision {
  if (out.outcome !== "mirrored") return "skip";
  const row = out.mapped.find((r) => r.productId === PLAY_SUBSCRIPTION_ID);
  if (!row) return "fall_back";
  if (row.status === "active" && Date.parse(row.storeExpiresIso) > nowMs) return "claim";
  if (row.status === "active") return "wait"; // renewal window or billing grace: Google has not moved the period yet
  return "fall_back";
}

async function freshDecision(deps: ReconcileDeps, uid: string, nowMs: number): Promise<Decision> {
  try {
    return decide(await deps.mirror(uid), nowMs);
  } catch (_) {
    return "wait"; // a read error never falls back or claims
  }
}

export type RunSummary = Record<string, number | string>;

export type DrainSummary = {
  claimed: number; applied: number; fell_back: number; waiting: number; skipped: number; back_to_pending: number;
  needs_check: number; errors: number; not_reached: number;
};

async function drainRow(deps: ReconcileDeps, row: DeferralRow, nowMs: number, s: DrainSummary): Promise<void> {
  const d = await freshDecision(deps, row.user_id, nowMs);
  // A row that waits (renewal window, grace, a read error) or is skipped goes to the back of the queue: otherwise 20 such
  // rows would hold the batch and no newer row would ever be reached (B-pass round 2, F3).
  if (d === "skip") { s.skipped++; await deps.db.touch(row.id); return; }
  if (d === "wait") { s.waiting++; await deps.db.touch(row.id); return; }
  if (d === "fall_back") {
    if ((await deps.db.fallBack(row.id, null)) === "fell_back") s.fell_back++;
    return;
  }
  const token = await deps.db.claim(row.id);
  if (!token) { s.skipped++; return; } // another run has it, or another defer is in flight for this user
  s.claimed++;

  let status: number | null = null;
  try {
    status = await deps.postDefer(row.user_id, row.days);
  } catch (_) {
    status = null; // timeout / network: outcome unknown
  }

  if (status !== null && status >= 200 && status < 300) {
    if (await deps.db.mark(row.id, token, "applied")) s.applied++;
    try { await deps.mirror(row.user_id); } catch (_) { /* the webhook and the next run mirror it */ }
  } else if (status === 429) {
    if (await deps.db.mark(row.id, token, "pending")) s.back_to_pending++;
  } else if (status !== null && status >= 400 && status < 500) {
    // Refused, so nothing was applied. Decide again on a fresh read.
    let again: Decision;
    try { again = decide(await deps.mirror(row.user_id), nowMs); } catch (_) { again = "wait"; }
    if (again === "fall_back") {
      if ((await deps.db.fallBack(row.id, token)) === "fell_back") s.fell_back++;
    } else if (again === "wait" || again === "skip") {
      if (await deps.db.mark(row.id, token, "pending")) s.back_to_pending++;
    } else if (await deps.db.mark(row.id, token, "needs_check")) {
      // Still active and Google refused: falling back would run the days alongside paid time, so a human decides.
      s.needs_check++;
    }
  } else {
    // 5xx, timeout, network: the defer MAY have been applied. Never re-send; a human checks.
    if (await deps.db.mark(row.id, token, "needs_check")) s.needs_check++;
  }
}

export async function runDrain(
  deps: ReconcileDeps,
  nowMs: number,
  deadlineMs = Number.POSITIVE_INFINITY,
  clock: () => number = () => nowMs,
): Promise<DrainSummary> {
  const s: DrainSummary = {
    claimed: 0, applied: 0, fell_back: 0, waiting: 0, skipped: 0, back_to_pending: 0, needs_check: 0, errors: 0, not_reached: 0,
  };
  const rows = await deps.db.pendingRows(DRAIN_BATCH);
  for (let i = 0; i < rows.length; i++) {
    if (clock() >= deadlineMs) { s.not_reached = rows.length - i; break; }
    try {
      await drainRow(deps, rows[i], nowMs, s);
    } catch (e) {
      // One bad row (a lock, a vanished user, a failed write) must not starve the rows behind it.
      s.errors++;
      console.error(`[${FN_NAME}] drain row failed name=${errorName(e)}`);
    }
  }
  if (s.needs_check > 0) {
    await deps.alert(NEEDS_CHECK_ALERT_SOURCE, `${s.needs_check} referral defer(s) need a manual check in RevenueCat`, {
      needs_check: s.needs_check,
    });
  }
  return s;
}

const json = (status: number, body: Record<string, unknown>) =>
  new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } });

export async function handler(req: Request, deps: ReconcileDeps): Promise<Response> {
  if (!(await deps.authorized(req))) return json(401, { error: "Unauthorized" });
  const clock = deps.nowMs ?? Date.now;
  const now = clock();
  const deadline = now + RUN_BUDGET_MS;
  const logId = await deps.telemetryStart();
  try {
    // 1. Stall alert first: an early return below must never hide a stuck reward (migrations CLAUDE.md, stall rows).
    const st = await deps.db.stallCounts(now);
    if (st.pendingOld + st.inFlightOld + st.needsCheck > 0) {
      await deps.alert(STALL_ALERT_SOURCE, "Referral days for Play subscribers are waiting (pending > 24 h, in flight > 2 h, or needs check)", st);
    }

    // 2. Switch.
    if (!deps.mirrorEnabled()) {
      await deps.telemetryEnd(logId, "success", { httpStatus: 200, errorSummary: "switch_off" });
      return json(200, { skipped: "switch_off", ...st });
    }

    // 3. Crashed claims.
    let crashed = 0;
    for (const c of await deps.db.crashedInFlight(now)) {
      if (await deps.db.mark(c.id, c.token, "needs_check")) crashed++;
    }
    if (crashed > 0) {
      await deps.alert(NEEDS_CHECK_ALERT_SOURCE, `${crashed} referral defer(s) were left in flight by a crashed run`, { crashed });
    }

    // 4. Drain (before the reconcile: see the header).
    const drain = await runDrain(deps, now, deadline, clock);

    // 5. Reconcile, inside the same budget.
    let mirrored = 0, other = 0, failed = 0, notReached = 0;
    const codes: Record<string, number> = {};
    const uids = await deps.db.reconcileUids(now);
    for (let i = 0; i < uids.length; i++) {
      if (clock() >= deadline) { notReached = uids.length - i; break; }
      try {
        if ((await deps.mirror(uids[i])).outcome === "mirrored") mirrored++;
        else other++;
      } catch (e) {
        failed++;
        const code = e instanceof RevenueCatReadError ? e.code : (e as { name?: string })?.name ?? "error";
        codes[code] = (codes[code] ?? 0) + 1;
      }
    }

    const summary = {
      mirrored, mirror_other: other, mirror_failed: failed, reconcile_not_reached: notReached, crashed,
      ...Object.fromEntries(Object.entries(drain).map(([k, v]) => [k === "errors" ? "drain_errors" : k === "not_reached" ? "drain_not_reached" : k, v])),
    };
    console.log(`[${FN_NAME}] ${Object.entries(summary).map(([k, v]) => `${k}=${v}`).join(" ")}`);
    // A run in which no reconcile read reached RevenueCat successfully while some failed (RevenueCat down, the secret key
    // unset) or a drain row errored is a FAILED run, so the cron-failure alert sees it. `other` (refused uid, unknown user)
    // returns before any RevenueCat call, so it proves nothing about RevenueCat (B-pass round 2, F2). More failed reads than
    // good ones is failed too: one lucky read in 200 must not record an outage as a success (hermes seat 2, 2026-11-24).
    const bad = (failed > 0 && failed > mirrored) || drain.errors > 0;
    if (notReached > 0 && mirrored + other + failed === 0) {
      await deps.alert(RECONCILE_STARVED_ALERT_SOURCE, "The referral drain used the whole run budget; no Play re-read ran this hour", {
        reconcile_not_reached: notReached,
      });
    }
    const parts = [
      failed > 0 ? `mirror_failed=${failed} codes=${Object.entries(codes).map(([k, v]) => `${k}:${v}`).join(",")}` : "",
      drain.errors > 0 ? `drain_errors=${drain.errors}` : "",
      notReached + drain.not_reached > 0 ? `budget_cut=${notReached + drain.not_reached}` : "",
    ].filter((x) => x);
    await deps.telemetryEnd(logId, bad ? "failed" : "success", {
      httpStatus: bad ? 500 : 200,
      errorSummary: parts.length > 0 ? parts.join(" ") : undefined,
    });
    return json(bad ? 500 : 200, summary);
  } catch (e) {
    const name = (e as { name?: string })?.name ?? "error";
    console.error(`[${FN_NAME}] run failed ${name}`);
    await deps.telemetryEnd(logId, "failed", { httpStatus: 500, errorSummary: `run failed ${name}` });
    return json(500, { error: "Internal server error" });
  }
}

/**
 * paged_fetch — bounded reads for cron Edge Functions (OI-79).
 *
 * ## The bug this exists to prevent
 *
 * PostgREST caps every response at `db-max-rows` (1000 on this project) and
 * **supabase-js gives you no way to notice**. Measured live 2026-08-01 against
 * `dedsavbjuwgarrhphgnl`, `food_database` (1431 rows):
 *
 * | request                                   | status | Content-Range | rows |
 * |-------------------------------------------|--------|---------------|------|
 * | `?select=id` (what `.select()` sends)      | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 0-1499`                            | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 1000-1999`                         | 200 OK | `1000-1430/*` |  431 |
 * | `Prefer: count=exact`                      | 206    | `0-999/1431`  | 1000 |
 *
 * Three things follow, and each one is load-bearing:
 *
 * 1. **It is a 200, not a 206.** OI-79 was filed saying truncation shows up as
 *    `206 Partial Content`. That is only true when the caller asks for a count,
 *    and no cron function here does. In the shape our code actually sends, the
 *    response is a plain `200 OK` with a short body and `error === null`. There
 *    is no status, no error, and no total (`/*`) to compare against — a
 *    truncated read is *byte-for-byte indistinguishable* from a small one. The
 *    only signal is the row count, and it is AMBIGUOUS: a page shorter than
 *    `pageSize` means either end-of-data or a server cap below `pageSize`.
 *    That is why the loop terminates on an EMPTY page, never a short one.
 * 2. **`.range()` cannot raise the cap.** Asking for 0-1499 still yields 1000.
 *    So `pageSize` MUST be <= the cap; a larger value does not fetch more, it
 *    silently breaks the loop (you ask for 1500, get 1000, read that as a short
 *    page, and stop early — dropping every row after the first page).
 * 3. **Paging past the cap works.** Offset 1000-1999 returns the remainder.
 *    A `.range()` loop is therefore a real fix, not a workaround.
 *
 * ## Why `orderBy` is required and has no default
 *
 * Postgres guarantees no row order without an `ORDER BY`, and PostgREST adds
 * none. Two `.range()` calls against an unordered relation may return
 * overlapping or disjoint slices, so a paginated loop without a stable sort key
 * can **duplicate or skip rows** — silently, and only under load. Three loops in
 * this repo shipped that way (`morning-alert`, `weekly-recap-ready`,
 * `weekly-recalc`); `i-see-you-callout` got it right with
 * `.order("id", { ascending: true })`. Making `orderBy` a required parameter
 * with no default is how that mistake becomes unconstructible here.
 *
 * Pick a key that is **unique and immutable** — a primary key. A non-unique key
 * (`date`, `status`) does not fully order the rows, so ties can shuffle between
 * page requests and reintroduce the same skip/duplicate bug.
 *
 * ## RPCs
 *
 * `.order()` / `.range()` are accepted on `/rpc/` set-returning functions, so
 * both helpers work with `() => supabase.rpc(...)`. Whether `db-max-rows` also
 * caps RPC responses could not be settled from here: the only anon-executable
 * set-returning functions on this project are not `SECURITY DEFINER`, so RLS
 * returns 0 rows to `anon` and the probe is inconclusive. It does not change
 * anything — these helpers page unconditionally, which is correct either way
 * (if the cap does not apply, the loop simply ends on the first empty page).
 *
 * @see docs/audit/open_issues.md OI-79
 */

// deno-lint-ignore-file no-explicit-any

/**
 * PostgREST's server-side `db-max-rows` for this project, confirmed live
 * (table above). A response can never exceed this many rows regardless of the
 * requested `Range`.
 */
export const POSTGREST_MAX_ROWS = 1000;

/** Default page size. Sits at the cap: the largest value that is still safe. */
export const DEFAULT_PAGE_SIZE = 1000;

/**
 * Default `.in()` chunk size. Bounds the **request URL**, which is a different
 * constraint from `pageSize` (which bounds the *response*). A uuid costs ~37
 * bytes in `in.(...)`, so 100 ids is ~3.7KB and stays clear of the ~4-8KB URL
 * limits proxies impose. Matches the existing `BATCH_SIZE = 100` precedent in
 * `evaluate-rank-promotions`.
 */
export const DEFAULT_CHUNK_SIZE = 100;

/**
 * Runaway guard. At the default page size this permits 10M rows, far beyond any
 * legitimate cron scan — it exists to turn "PostgREST keeps returning full
 * pages forever" (an unstable sort key, a clock-skewed filter) into a loud
 * failure instead of an Edge Function that runs until the platform kills it.
 */
export const DEFAULT_MAX_PAGES = 10_000;

/** Minimal structural shape we need from a supabase-js query builder. */
interface RangeableBuilder {
  order(column: string, opts: { ascending: boolean }): RangeableBuilder;
  range(from: number, to: number): PromiseLike<{ data: unknown; error: unknown }>;
}

/** One ORDER BY term. */
export interface OrderKey {
  column: string;
  ascending?: boolean;
}

export interface PagedFetchOptions {
  /**
   * REQUIRED. Sort key — must be unique and immutable (a primary key). See the
   * header note on why this has no default.
   *
   * Pass an array to sort by several columns, e.g. to page a "most recent row
   * per user" read while preserving its ordering semantics:
   * `[{ column: "snapshot_date", ascending: false }, { column: "id" }]`.
   * The **last** term must be unique — the earlier ones can tie, and ties
   * without a unique tiebreaker are exactly the unstable-page bug.
   */
  orderBy: string | OrderKey[];
  /**
   * Sort direction for the single-column form. Ignored when `orderBy` is an
   * array (each term carries its own).
   */
  ascending?: boolean;
  /** Rows per request. MUST be <= {@link POSTGREST_MAX_ROWS}; see header note 2. */
  pageSize?: number;
  /** Runaway guard, see {@link DEFAULT_MAX_PAGES}. */
  maxPages?: number;
  /** Prefix for the saturation log line. Defaults to "paged_fetch". */
  label?: string;
}

/** Normalises the `orderBy` union into a non-empty list of ORDER BY terms. */
function orderKeys(opts: PagedFetchOptions): OrderKey[] {
  const bad = () => {
    throw new Error(
      "paged_fetch: `orderBy` is required and must be a non-empty column name " +
        "(or a non-empty array of them). A .range() loop without a stable sort " +
        "key can skip or duplicate rows (OI-79).",
    );
  };

  if (typeof opts.orderBy === "string") {
    if (!opts.orderBy.trim()) bad();
    return [{ column: opts.orderBy, ascending: opts.ascending ?? true }];
  }
  if (!Array.isArray(opts.orderBy) || opts.orderBy.length === 0) bad();
  const keys = (opts.orderBy as OrderKey[]).map((k) => {
    if (!k || typeof k.column !== "string" || !k.column.trim()) bad();
    return { column: k.column, ascending: k.ascending ?? true };
  });
  return keys;
}

function validate(opts: PagedFetchOptions): { pageSize: number; maxPages: number } {
  orderKeys(opts); // throws when the sort key is missing or malformed
  const pageSize = opts.pageSize ?? DEFAULT_PAGE_SIZE;
  if (!Number.isInteger(pageSize) || pageSize < 1) {
    throw new Error(`paged_fetch: pageSize must be a positive integer, got ${pageSize}`);
  }
  if (pageSize > POSTGREST_MAX_ROWS) {
    throw new Error(
      `paged_fetch: pageSize ${pageSize} exceeds PostgREST's db-max-rows ` +
        `(${POSTGREST_MAX_ROWS}). A larger page cannot fetch more rows — the server ` +
        `silently clamps it — so every page costs a full round-trip for at most ` +
        `${POSTGREST_MAX_ROWS} rows while the arithmetic implies more. The loop itself is ` +
        `SAFE at any cap (it advances by rows received and stops only on an empty page), ` +
        `so this is a wrong-configuration guard, not a correctness one. ` +
        `Use a pageSize <= ${POSTGREST_MAX_ROWS} (OI-79).`,
    );
  }
  const maxPages = opts.maxPages ?? DEFAULT_MAX_PAGES;
  if (!Number.isInteger(maxPages) || maxPages < 1) {
    throw new Error(`paged_fetch: maxPages must be a positive integer, got ${maxPages}`);
  }
  return { pageSize, maxPages };
}

/**
 * Reads **every** row matching a query, paging until an EMPTY page arrives.
 *
 * `makeQuery` must return a fresh builder each call — supabase-js builders are
 * single-use thenables, so reusing one across pages does not work. Apply your
 * filters there and let this apply `.order()` and `.range()`:
 *
 * ```ts
 * const rows = await fetchAllPages<{ user_id: string }>(
 *   () => supabase.from("coach_memory").select("user_id").gte("dropout_risk_score", 0.5),
 *   { orderBy: "user_id", label: "re-engagement path A" },
 * );
 * ```
 *
 * Throws on the first page error rather than returning partial rows. That is
 * deliberate: silently proceeding with an incomplete candidate set is the exact
 * failure this module exists to prevent, and a cron tick that cannot read its
 * inputs should fail loudly and retry on the next tick.
 */
export async function fetchAllPages<T>(
  makeQuery: () => unknown,
  opts: PagedFetchOptions,
): Promise<T[]> {
  const { pageSize, maxPages } = validate(opts);
  const keys = orderKeys(opts);
  const label = opts.label ?? "paged_fetch";
  const keyDesc = keys.map((k) => `${k.column}${k.ascending ? "" : " desc"}`).join(", ");

  const all: T[] = [];

  for (let page = 0; ; page++) {
    if (page >= maxPages) {
      throw new Error(
        `paged_fetch[${label}]: exceeded maxPages=${maxPages} (${all.length} rows read). ` +
          `Every page came back full — check that orderBy='${keyDesc}' ends in a unique, ` +
          `immutable column; an unstable sort key can loop forever.`,
      );
    }

    // Offset by rows ACTUALLY received, never by `page * pageSize`. The two
    // agree only while the server serves full pages, and `db-max-rows` is a
    // dashboard setting (Settings -> API -> Max rows), not a platform
    // invariant. Lower it to 500 and the old arithmetic broke completely:
    // page 0 asked 0-999, got 500, and `500 < pageSize` read as end-of-data —
    // so every one of the reads this module was written to fix would silently
    // return 500 rows with error === null. Advancing by `all.length` makes the
    // loop correct for ANY server cap without having to know what it is.
    const from = all.length;
    const to = from + pageSize - 1;

    let q = makeQuery() as RangeableBuilder;
    for (const k of keys) q = q.order(k.column, { ascending: k.ascending ?? true });
    const builder = q.range(from, to);

    const { data, error } = await builder;
    if (error) {
      throw new Error(
        `paged_fetch[${label}]: page ${page} (rows ${from}-${to}) failed: ` +
          `${(error as { message?: string } | null)?.message ?? String(error)}`,
      );
    }

    const rows = (data ?? []) as T[];
    all.push(...rows);

    // Only an EMPTY page proves end-of-data. A SHORT page does not: it is
    // equally the signature of a server cap below `pageSize` (see the offset
    // note above), and treating it as "done" is exactly the silent truncation
    // this module exists to prevent.
    //
    // COST, stated honestly. For `fetchAllPages` this is one extra round-trip
    // per read. For `fetchAllByIds` it is one extra per CHUNK, and with
    // DEFAULT_CHUNK_SIZE = 100 a chunk essentially never fills a 1000-row
    // page — so the confirming request lands on ~every chunk, not on a rare
    // boundary. 12 chunked call sites; at ~10k PRO users protein-gap-alert
    // goes from roughly 300 to 600 sequential round-trips per tick. Accepted
    // deliberately: these are daily cron jobs where wall-clock is cheap, and
    // the alternative is a read that silently returns half its rows with
    // error === null. If round-trips ever become the constraint, learn the
    // server's real page size once per process instead. (Corrected after
    // round-2 review — the earlier note claimed "the same one the
    // exact-multiple case already paid", true of fetchAllPages and NOT of the
    // chunked path that dominates.)
    if (rows.length === 0) break;
  }

  return all;
}

/**
 * Reads every row for a set of ids, chunking the `.in()` list **and** paging
 * within each chunk.
 *
 * Chunking alone is not enough, and that distinction is the whole point of this
 * function. `evaluate-rank-promotions` already had a `fetchInChunks` helper that
 * split `userIds` into batches of 100 — but a chunk bounds the *request*, not
 * the *response*. One 100-id chunk against a table holding N rows per user
 * returns 100xN rows, so it truncates at 10 rows/user no matter how small the
 * chunk is. This pages inside each chunk, which bounds both.
 *
 * ```ts
 * const logs = await fetchAllByIds<{ user_id: string }>(
 *   (chunk) => supabase.from("nutrition_logs")
 *                      .select("user_id, total_protein")
 *                      .eq("date", todayIST)
 *                      .in("user_id", chunk),
 *   proUserIds,
 *   { orderBy: "id", label: "protein-gap-alert nutrition" },
 * );
 * ```
 */
export async function fetchAllByIds<T>(
  makeQuery: (idChunk: string[]) => unknown,
  ids: string[],
  opts: PagedFetchOptions & { chunkSize?: number },
): Promise<T[]> {
  validate(opts);

  const chunkSize = opts.chunkSize ?? DEFAULT_CHUNK_SIZE;
  if (!Number.isInteger(chunkSize) || chunkSize < 1) {
    throw new Error(`paged_fetch: chunkSize must be a positive integer, got ${chunkSize}`);
  }

  if (ids.length === 0) return [];

  const all: T[] = [];
  for (let i = 0; i < ids.length; i += chunkSize) {
    const chunk = ids.slice(i, i + chunkSize);
    const rows = await fetchAllPages<T>(() => makeQuery(chunk), {
      ...opts,
      label: `${opts.label ?? "paged_fetch"} chunk@${i}`,
    });
    all.push(...rows);
  }
  return all;
}
